import React from 'react';
import { useNavigate } from 'react-router-dom';

const services = [
  {
    id: 1,
    title: "Tổ chức tiệc cưới",
    desc: "Tổ chức lễ cưới chuyên nghiệp, sang trọng và theo yêu cầu cá nhân hóa cho từng cặp đôi.",
    path: "/service/wedding"
  },
  {
    id: 2,
    title: "Sinh nhật & Kỷ niệm",
    desc: "Trang trí và tổ chức tiệc sinh nhật, kỷ niệm với nhiều phong cách và gói dịch vụ linh hoạt.",
    path: "/service/birthday"
  },
  {
    id: 3,
    title: "Sự kiện công ty",
    desc: "Tổ chức hội nghị, gala dinner, team building với quy mô từ nhỏ đến lớn, chuyên nghiệp và hiệu quả.",
    path: "/service/corporate"
  },
  {
    id: 4,
    title: "Trang trí tiệc theo chủ đề",
    desc: "Cung cấp dịch vụ trang trí không gian tiệc theo các chủ đề độc đáo và phong cách.",
    path: "/service/decor"
  }
];

function Home() {
  const navigate = useNavigate();
  const isLoggedIn = !!JSON.parse(localStorage.getItem("currentUser"));

  const handleClick = (path) => {
    if (isLoggedIn) {
      navigate(path);
    } else {
      alert("Vui lòng đăng nhập để xem chi tiết dịch vụ.");
      navigate("/login");
    }
  };

  return (
    <div className="container py-4">
      <div className="bg-warning-subtle p-4 rounded shadow-sm mb-4 text-center">
        <h2>Chào mừng đến với PartyPlanner Pro</h2>
        <p>
          Chúng tôi chuyên cung cấp dịch vụ tổ chức tiệc trọn gói: từ tiệc cưới, sinh nhật đến sự kiện doanh nghiệp với phong cách chuyên nghiệp và sáng tạo.
        </p>
      </div>
      <h3 className="text-center mb-4">Dịch vụ nổi bật</h3>
      <div className="row">
        {services.map(service => (
          <div className="col-12 col-md-6 mb-4" key={service.id}>
            <div className="card h-100 border-primary shadow-sm">
              <div className="card-body d-flex flex-column">
                <h5 className="card-title text-primary">{service.title}</h5>
                <p className="card-text flex-grow-1">{service.desc}</p>
                <button
                  className="btn btn-outline-primary mt-2"
                  onClick={() => handleClick(service.path)}
                >
                  Xem chi tiết
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Home;
